import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_cam_qtp_01_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cam_qtp_01", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.260985626087376e+00, -3.197568882931729e+00, -3.108738698915428e+00, -2.985751443121991e+00, -2.818293443769223e+00, -2.595660653528762e+00, -2.309515590593334e+00, -1.958676190681834e+00, -1.554832882563325e+00, -1.123548441286738e+00, -7.012165413718821e-01, -4.499824980091320e-01, -3.783820097817279e-01, -2.925922995147986e-01, -1.763750904382133e-01, -6.545936736880534e-02, -7.656850581736282e-03, -2.581414350341731e-03, -5.181650492195157e-04, -6.542151319532907e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


